I'm pretty sure this can be done with botPolicy, correct me if I'm wrong.
Edit: This is working for me:

```nix
services.anubis = {
  defaultOptions.settings = {
    BIND_NETWORK = "tcp";
    METRICS_BIND_NETWORK = "tcp";
  };

  instances.buildbot = {
    settings = {
      BIND = ":61238";
      METRICS_BIND = ":61239";
      TARGET = "http://127.0.0.1:8010";
    };

    botPolicy.bots = [
      {
        name = "generic-browser";
        user_agent_regex = "Mozilla|Opera";
        action = "CHALLENGE";
        challenge = {
          difficulty = 1;
          algorithm = "metarefresh";
        };
      }
    ];
  };
};
```
